auditor:
(() => {
  window.__actionAudit=[];
  for(const type of ['keydown','keyup','pointerdown','pointerup','pointermove','click','contextmenu','wheel','beforeinput','input','change']) document.addEventListener(type,event=>{
    if(window.__actionAudit.length<1000) window.__actionAudit.push({type,id:event.target.id,key:event.key||'',inputType:event.inputType||'',trusted:event.isTrusted,buttons:event.buttons||0,meta:!!event.metaKey,ctrl:!!event.ctrlKey,shift:!!event.shiftKey});
  },true);
  document.addEventListener('contextmenu',event=>event.preventDefault());
})()

