(() => {
    const fields={};for(const item of document.querySelectorAll('input,textarea,select,[contenteditable]')) {const editable=item.hasAttribute('contenteditable')&&item.getAttribute('contenteditable')!=='false';fields[item.id||item.getAttribute('aria-label')||item.type]={value:item.type==='password'?'masked':editable?item.innerText:item.value,html:editable?item.innerHTML:undefined,checked:['checkbox','radio'].includes(item.type)?item.checked:undefined,selected:item.selectedOptions?Array.from(item.selectedOptions).map(option=>option.label):undefined};}
    const value={fields,audit:window.__actionAudit||[],log:window.log||[],dropped:!!window.dropped,closedClicks:window.closedClicks||0,closedTrusted:!!window.closedTrusted,nestedClicked:document.body.dataset.nestedClicked,recreatedClicked:document.body.dataset.recreatedClicked,frameClicked:document.querySelector('#same')?.contentDocument?.body.dataset.clicked,hover:document.querySelector('#hover-state')?.textContent,scroll:document.querySelector('#scroller')?.scrollTop||0,pageScroll:scrollY,declarative:{height:document.querySelector('#declarative')?.getBoundingClientRect().height||0,marker:document.querySelector('#declarative')?.getAttribute('data-codenomad-shadow-boundary'),open:!!document.querySelector('#declarative')?.shadowRoot,templates:window.declarativeTemplates||0}};
    value.capabilities={predictedEvents:typeof PointerEvent.prototype.getPredictedEvents};
    let output=document.getElementById('__cn_probe');if(!output){output=document.createElement('output');output.id='__cn_probe';output.style='position:fixed;right:0;bottom:0;font-size:1px;pointer-events:none';document.body.append(output)}output.textContent='__CN_PROBE__'+JSON.stringify(value);
  })()
